msg.host = global.get('clusterServer') || 'dxc.ve7cc.net';
msg.port = parseInt(global.get('clusterPort')) || 23;
msg.payload = '\r\n';
return msg;

let line = msg.payload;
if (typeof line !== 'string') line = String(line);
line = line.replace(/\r/g, '').trim();
if (!line) return null;
msg.payload = line;
return msg;

const line = msg.payload;
// DX de <spotter>:  <freq>  <call>  <comment>  <HHMM>Z
const regex = /^DX de\s+([^:]+):\s+([\d.]+)\s+(\S+)\s+(.*?)\s+(\d{4})Z\s*$/;
const m = line.match(regex);
if (!m) return null;
return {
    payload: {
        de: m[1].trim(),
        freq: parseFloat(m[2]),
        call: m[3].trim(),
        comment: m[4].trim(),
        time: m[5]
    }
};

const monitored = global.get('monitoredCalls') || [];
const call = msg.payload.call;
if (!call) return null;
const upper = call.toUpperCase();
const list = monitored.map(c => String(c).toUpperCase());
if (!list.includes(upper)) return null;
msg.payload.monitored_call = upper;
return msg;

const spot = msg.payload;
const de = spot.de;
const cache = global.get('callsignCache') || {};

let lat, lon;
if (cache[de] && cache[de].lat !== undefined) {
    lat = cache[de].lat;
    lon = cache[de].lon;
} else {
    try {
        const res = await httpRequest({url: 'https://api.hamdb.org/' + encodeURIComponent(de) + '/json/nodered'});
        if (res && res.hamdb && res.hamdb.callsign) {
            lat = parseFloat(res.hamdb.callsign.lat);
            lon = parseFloat(res.hamdb.callsign.lon);
            if (!isNaN(lat) && !isNaN(lon)) {
                cache[de] = {lat: lat, lon: lon, ts: Date.now()};
                global.set('callsignCache', cache);
            } else {
                lat = undefined; lon = undefined;
            }
        }
    } catch (e) {
        node.warn('hamdb lookup failed for ' + de + ': ' + e.message);
    }
}

if (lat === undefined || lon === undefined || isNaN(lat) || isNaN(lon)) return null;

// Distance (haversine) from home
const homelat = parseFloat(global.get('homelat')) || 0;
const homelon = parseFloat(global.get('homelon')) || 0;
function deg2rad(d) { return d * Math.PI / 180; }
const R = 6371;
const dLat = deg2rad(lat - homelat);
const dLon = deg2rad(lon - homelon);
const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
          Math.cos(deg2rad(homelat)) * Math.cos(deg2rad(lat)) *
          Math.sin(dLon/2) * Math.sin(dLon/2);
const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
const distKm = R * c;

// Signal / mode extraction from comment
const comment = spot.comment || '';
let snr = null, signal = null, mode = null;
const snrMatch = comment.match(/(-?\d+)\s*dB/i);
if (snrMatch) snr = parseInt(snrMatch[1]);
const sigMatch = comment.match(/\b([1-5][1-9][1-9]?)\b/);
if (sigMatch) signal = sigMatch[1];
if (/\bCW\b/i.test(comment)) mode = 'CW';
else if (/\b(FT8|FT4|RTTY|PSK|JT65|JT9|JS8)\b/i.test(comment)) mode = 'DIGI';
else if (/\b(SSB|USB|LSB|AM|FM)\b/i.test(comment)) mode = 'PHONE';

spot.lat = lat;
spot.lon = lon;
spot.distance_km = Math.round(distKm);
spot.distance_miles = Math.round(distKm * 0.62137);
spot.snr = snr;
spot.signal = signal;
spot.mode = mode;
spot.timestamp = new Date().toISOString();

return {payload: spot};

const s = msg.payload;
const esc = (v) => v === null || v === undefined ? 'NULL' : ("'" + String(v).replace(/'/g, "''") + "'");
const num = (v) => v === null || v === undefined || isNaN(v) ? 'NULL' : v;
msg.topic = `INSERT INTO spots (timestamp, monitored_call, de, freq, spot_call, comment, spot_time, mode, signal, snr, lat, lon, distance_km, distance_miles) VALUES (${esc(s.timestamp)}, ${esc(s.monitored_call)}, ${esc(s.de)}, ${num(s.freq)}, ${esc(s.call)}, ${esc(s.comment)}, ${esc(s.time)}, ${esc(s.mode)}, ${esc(s.signal)}, ${num(s.snr)}, ${num(s.lat)}, ${num(s.lon)}, ${num(s.distance_km)}, ${num(s.distance_miles)});`;
return msg;

// Pass the enriched spot object to the websocket out node.
// The websocket-listener broadcasts msg.payload to all clients.
return msg;

let calls = msg.payload;
if (typeof calls === 'string') {
    try { calls = JSON.parse(calls); } catch (e) { calls = calls.split(',').map(c => c.trim()).filter(Boolean); }
}
if (!Array.isArray(calls)) calls = [];
calls = calls.map(c => String(c).toUpperCase()).filter(Boolean).slice(0, 9);
global.set('monitoredCalls', calls);
msg.headers = {'Content-Type': 'application/json'};
msg.payload = {success: true, calls: calls};
return msg;

const call = msg.req.query.call;
const limit = parseInt(msg.req.query.limit) || 1000;
const esc = (v) => "'" + String(v).replace(/'/g, "''") + "'";
let sql = 'SELECT * FROM spots';
if (call) {
    const c = call.toUpperCase();
    sql += ' WHERE monitored_call = ' + esc(c) + ' OR spot_call = ' + esc(c);
}
sql += ' ORDER BY id DESC LIMIT ' + limit;
msg.topic = sql;
msg.headers = {'Content-Type': 'application/json'};
return msg;

msg.headers = {'Content-Type': 'application/json'};
msg.payload = {
    homelat: global.get('homelat') || '',
    homelon: global.get('homelon') || '',
    clusterServer: global.get('clusterServer') || 'dxc.ve7cc.net',
    clusterPort: global.get('clusterPort') || '23',
    skimmerCall: global.get('skimmerCall') || ''
};
return msg;

const cfg = msg.payload || {};
if (cfg.homelat !== undefined) global.set('homelat', cfg.homelat);
if (cfg.homelon !== undefined) global.set('homelon', cfg.homelon);
if (cfg.clusterServer !== undefined) global.set('clusterServer', cfg.clusterServer);
if (cfg.clusterPort !== undefined) global.set('clusterPort', cfg.clusterPort);
if (cfg.skimmerCall !== undefined) global.set('skimmerCall', cfg.skimmerCall);
msg.headers = {'Content-Type': 'application/json'};
msg.payload = {success: true};
return msg;

msg.host = global.get('clusterServer') || 'dxc.ve7cc.net';
msg.port = parseInt(global.get('clusterPort')) || 23;
msg.payload = (global.get('skimmerCall') || 'DX-COMPASS') + '\r\n';
msg.headers = {'Content-Type': 'application/json'};
return msg;
